-- SCRIPT EXEMPLOS DQL/DRS
-- DQL/DRS - LING. DE CONSULTA/RECUPERAÇÃO DE DADOS
-- SUGESTÃO NOME SCRIPT
-- SCRIPT_DQL_DRS_EXEMPLOS.SQL
 
-- COMANDO : SELEC
-- SINTAXE
-- SELECT <COLUNAS>
-- FROM <TABELA(S)>
-- WHERE <CONDIÇÃO>
-- OUTRAS CLAUSULAS  -> ORDER BY, GROUP BY .
 
-- RECUPERAR A TABELA INTEIRA
--(*ASTERISCO) - TODAS AS COLUNAS
--AUSENCIA DO WHERE -> INDICA A RECUPERAÇÃO DE TODAS AS LINHAS
 
SELECT * FROM T_SIP_DEPARTAMENTO;
-- OBSERVAÇÃO: NÃO É BOA PRATICA USAR EM PRODUÇÃO, AO
-- MENOS QUE A NECESSIDADE, SEJA REALMENTE RECUPERAR
-- UMA TABELA INTEIRA
 
-- BOA PRATICA - INFORMO COLUNAS E CONDIÇÃO
-- RECUPERANDO OS FUNCIONARIOS ADMITIDOS A PARTIR DE
-- 01/01/2018
SELECT NR_MATRICULA, NM_FUNCIONARIO, VL_SALARIO_MENSAL
   FROM T_SIP_FUNCIONARIO
  WHERE DT_ADMISSAO >= TO_DATE ('01/01/2018', 'DD/MM/YYYY');
 
 -- QUAIS FUNCIONARIOS POSSUEM DEPENDENTES
SELECT NR_MATRICULA
  FROM T_SIP_DEPENDENTE;
 
  -- DISTINCT RECUPERA OS DADOS DE UMA COLUNA SEM REPETIÇÃO
  SELECT DISTINCT NR_MATRICULA
  FROM T_SIP_DEPENDENTE;
  --OU
  SELECT UNIQUE NR_MATRICULAFROM T_SIP_DEPENDENTE;
 
  -- QUAIS DEPTOS POSSUEM FUNCIONARIOS TRABALHANDO?
  SELECT UNIQUE CD_DEPARTAMENTO
  FROM T_SIP_FUNCIONARIO;
 
  -- SIMULAÇÃO DE AUMNETO DE SALÁRIO EM 10%
  -- PARA TODOS OS FUNCIONARIOS
  SELECT NR_MATRICULA, NM_FUNCIONARIO,
  VL_SALARIO_MENSAL,
  VL_SALARIO_MENSAL * 1.10
  FROM T_SIP_FUNCIONARIO;
 
 --ALIAS -> APELIDO DE COLUNA
  SELECT NM_MATRICULA, NM_FUNCIONARIO,
  VL_SALARIO_MENSAL,
  VL_SALARIO_MENSAL * 1.10 AS "SIMULAÇÃPDE SALÁRIO" --ASPA DUPLA
  FROM T_SIP_FUNCIONARIO
 
--ORDENAR OS RESULTADOS
-- ORDERNAR POR UMA OU AIS COLUNAS
-- CRESCENTE (DEFAULT) -> ASC
-- DECRESCENTE -> DESC
SELECT NM_MATRICULA, NM_FUNCIONARIO,
CD_DEPARTAMENTO,
VL_SALARIO_MENSAL AS SALARIO,
VL_SALARIO_MENSAL * 1.10 AS "SIMULAÇÃO DE SALÁRIO"
FROM T_SIP_FUNCIONARIO
ORDER BY CD_DEPARTAMENTO ASC,
"SIMULAÇÃO DE SALÁRIO" DESC;
 
-- OUTRA FORMA - CUIDADO NA ORDEM DAS COLUNAS
ELECT NM_MATRICULA, NM_FUNCIONARIO,
CD_DEPARTAMENTO,
VL_SALARIO_MENSAL AS SALARIO,
VL_SALARIO_MENSAL * 1.10 AS "SIMULAÇÃO DE SALÁRIO"
FROM T_SIP_FUNCIONARIO
ORDER BY 3 ASC, 5 DESC;
 
-- CONDIÇÃO
-- RECUPERAR TODOS OS FUNCIONARIOS DO DEPTO DE CODIGO = 1
-- ALEM DA SIMULAÇÃO DO SALÁRIO
SELECT NM_MATRICULA, NM_FUNCIONARIO,
CD_DEPARTAMENTO,
VL_SALARIO_MENSAL AS SALARIO,
VL_SALARIO_MENSAL * 1.10 AS "SIMULAÇÃO DE SALÁRIO"
FROM T_SIP_FUNCIONARIO
WHERE CD_DEPARTAMENTO = 1
ORDER BY CD_DEPARTAMENTO ASC,
"SIMULAÇÃO DE SALÁRIO" DESC;
 
-- OPERADORES RELACIONAIS:
-- = <> != < <= > >=
 
-- OPERADORES LÓGICOS
-- OR, AND, NOT
 
-- OR -> RECUPERA DADOS QND UMA DAS CONDIÇÕES  E SATISFEITA
SELECT NM_MATRICULA, NM_FUNCIONARIO,
CD_DEPARTAMENTO, DT_ADMISSAO,
VL_SALARIO_MENSAL AS SALARIO,
VL_SALARIO_MENSAL * 1.10 AS "SIMULAÇÃO DE SALÁRIO"
FROM T_SIP_FUNCIONARIO
WHERE CD_DEPARTAMENTO = 1 OR
DT_ADMISSAO >= TO DATE ('15/01/2018', 'DD/MM/YYYY'),
ORDER BY CD_DEPARTAMENTO ASC,
"SIMULAÇÃO DE SALÁRIO" DESC;
 
-- AND -> RECUPERA DADOS QUANDO TODAS AS CONDIÇÕES SÃO SATISFEITAS
 
SELECT NM_MATRICULA, NM_FUNCIONARIO,
CD_DEPARTAMENTO, DT_ADMISSAO,
VL_SALARIO_MENSAL AS SALARIO,
VL_SALARIO_MENSAL * 1.10 AS "SIMULAÇÃO DE SALÁRIO"
FROM T_SIP_FUNCIONARIO
WHERE CD_DEPARTAMENTO = 6 AND
DT_ADMISSAO >= TO DATE ('15/01/2018', 'DD/MM/YYYY'),
ORDER BY CD_DEPARTAMENTO ASC,
"SIMULAÇÃO DE SALÁRIO" DESC;
 
-- NOT -> NEGAÇÃO (VAI NEGAR A EXPRESSÃO INFORMADA)
SELECT NM_MATRICULA, NM_FUNCIONARIO,
CD_DEPARTAMENTO, DT_ADMISSAO,
VL_SALARIO_MENSAL AS SALARIO,
VL_SALARIO_MENSAL * 1.10 AS "SIMULAÇÃO DE SALÁRIO"
FROM T_SIP_FUNCIONARIO
WHERE NOT CD_DEPARTAMENTO = 6
DT_ADMISSAO >= TO DATE ('15/01/2018', 'DD/MM/YYYY'),
ORDER BY CD_DEPARTAMENTO ASC,
"SIMULAÇÃO DE SALÁRIO" DESC;
-- EQUIVALENTE
-- WHERE CD_DEPARTAMENTO <> 6
-- OU
-- WHERE CD_DEPARTAMENTO != 6  


COMMIT;
